import langextract as lx

prompt = "Extract characters, emotions, and relationships in order of appearance. Use exact text for extractions."
examples = [
    lx.data.ExampleData(
        text="ROMEO. But soft! What light through yonder window breaks? It is the east, and Juliet is the sun.",
        extractions=[
            lx.data.Extraction(extraction_class="character", extraction_text="ROMEO", attributes={"emotional_state": "wonder"}),
        ],
    )
]
